    CYC(5);
    hw_wr8(PKI2, A);                                 /* L76AC */
    M8(DREF) = A;                                    /* L76AF  CLEAR DYN. RECON. FLAG */
    CYC(17);
    JSR(s_pkcut1);                                   /* L76B1  .IRPC VNUM,<12345678>   */
    CYC(8);
    JSR(s_pkcut2);                                   /* L76B4  .IRPC VNUM,<12345678>   */
    CYC(8);
    JSR(s_pkcut3);                                   /* L76B7  .IRPC VNUM,<12345678>   */
    CYC(8);
