    CYC(5);
    hw_wr8(PKI2, A);                                 /* L76CE */
    A = 0x78;                                        /* L76D1  VOICES 3 AND 4 ARE 16 BIT EACH */
    CYC(7);
    hw_wr8(PKC1, A);                                 /* L76D3 */
